#!/usr/bin/env python3
"""Generate experiments/masm3/opbenches.glon (deterministic byte data)."""
from pathlib import Path

HERE = Path(__file__).resolve().parent
CHUNK = "".join(chr(97 + (i % 26)) for i in range(400))
SMALL = "ab"
PATTERN = "web"

src = f'''[
;; Generated by make_benches.py.  Loaded after the shipped libraries.
s400: "{CHUNK}"
s400b: "{CHUNK}"
carry: "{SMALL}"
pattern: "{PATTERN}"
bx: [10 20 30 40 50]
v1: 11
v2: 22
fields: [1 2]
ok: func [a b] [a]
bad: func [e] [e]

empty: does [ 0 ]
lit-empty: does [ "" ]
lit-one: does [ "x" ]
s-length: does [ s/length s400 ]
bench-block-at: does [ block-at bx 3 ]
bench-block-len: does [ block-len bx ]
slice-400: does [ s/slice s400 0 400 ]
slice-2: does [ s/slice s400 398 2 ]
slice-0: does [ s/slice s400 0 0 ]
raw-slice-400: does [ s/raw-slice s400 0 400 ]
raw-slice-2: does [ s/raw-slice s400 398 2 ]
raw-length: does [ s/raw-length s400 ]
cat-400x2: does [ s/+ s400 s400 ]
cat-400x2b: does [ s/+ carry s400 ]
raw-cat-400x2b: does [ s/raw-cat carry s400 ]
slice2-400: does [ s/slice2 s400 s400b 200 400 ]
slice2-4: does [ s/slice2 s400 s400b 398 4 ]
slice2-masm-400: does [ s/slice2-masm s400 s400b 200 400 ]
slice2-glon-400: does [ s/slice2-glon s400 s400b 200 400 ]
raw-slice2-400: does [ s/raw-slice2 s400 s400b 200 400 ]
slice2-stream: does [ s/slice2 carry s400 0 400 ]
slice2-glon-stream: does [ s/slice2-glon carry s400 0 400 ]
mk-small: does [ mk-string reduce [ 65 ] ]
reduce2: does [ reduce [ v1 v2 ] ]
reduce3: does [ reduce [ v1 v2 fields ] ]
reduce5: does [ reduce [ v1 v2 :ok :bad bx ] ]
u32: does [ io/u32 123456 ]
handle-field: does [ io/handle-field 1 ]
request-cycle: does [
    io/request 2 reduce [ io/handle-field 1 io/u32 400 ] :ok :bad 1
    io/reply io/pending-id 'ok s400 none
]
request-cycle-small: does [
    io/request 2 reduce [ io/handle-field 1 io/u32 400 ] :ok :bad 1
    io/reply io/pending-id 'ok s400 none
]
callback-none: does [
    combined: s/+ carry s400
    keep: - s/length pattern 1
    safe-len: - s/length combined keep
    safe: s/slice combined 0 safe-len
    next-carry: s/slice combined safe-len - s/length combined safe-len
    either = 0 s/length next-carry [ safe ] [ safe ]
]
]
'''

(HERE / "opbenches.glon").write_text(src)
print("wrote", HERE / "opbenches.glon")
